def odd_Equivalent(binary_string, n):
    count = 0
    length = len(binary_string)
    for i in range(n):
        rotated = binary_string[i % length:] + binary_string[:i % length]
        if int(rotated, 2) % 2 == 1:
            count += 1
    return count
