def max_sum_increasing_subseq(arr, n, i, k):
    target = arr[k]
    prefix = arr[:i]
    dp = [0] * i
    for j in range(i):
        if prefix[j] < target:
            dp[j] = prefix[j]
            for p in range(j):
                if prefix[p] < prefix[j] and dp[p] > 0:
                    dp[j] = max(dp[j], dp[p] + prefix[j])
    return max(0, max(dp) if dp else 0) + target
```

