def get_max_sum(n):
    from functools import lru_cache

    @lru_cache(maxsize=None)
    def f(x):
        if x <= 1:
            return x
        return max(f(x // 2) + f(x // 3) + f(x // 4) + f(x // 5), x)

    return f(n)
